{"content":"// Package words implements streaming word-count utilities.
package words

import (
	"bufio"
	"io"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

// WordCount pairs a word with the number of times it occurred.
type WordCount struct {
	Word  string
	Count int
}

// TopK streams r in chunks and returns the k most frequent words,
// by count descending, ties broken by the word ascending (byte order).
// If there are fewer than k distinct words, all of them are returned.
// A k <= 0 returns an empty (non-nil) slice.
//
// A word is a maximal run of Unicode letters or digits, optionally
// containing internal apostrophes between letters (don't, o'clock).
// Leading or trailing apostrophes are not part of the word; any other
// rune separates words. Words are case-folded with strings.ToLower and
// words present in stop (compared case-insensitively) are ignored.
func TopK(r io.Reader, k int, stop []string) ([]WordCount, error) {
	if k <= 0 {
		return []WordCount{}, nil
	}
	stopSet := make(map[string]struct{}, len(stop))
	for _, w := range stop {
		stopSet[strings.ToLower(w)] = struct{}{}
	}

	counts := make(map[string]int)
	br := bufio.NewReaderSize(r, 256*1024)

	flush := func(word []rune) {
		w := strings.ToLower(string(word))
		if _, ok := stopSet[w]; !ok {
			counts[w]++
		}
	}

	var word []rune
	for {
		ch, _, err := br.ReadRune()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		switch {
		case isLetterDigit(ch):
			word = append(word, ch)
		case isApostrophe(ch) && len(word) > 0:
			// Internal apostrophes may only sit between letters or
			// digits; consume only if another letter/digit follows.
			nch, _, nerr := br.ReadRune()
			if nerr == io.EOF {
				// Trailing apostrophe at end of input.
				break
			}
			if nerr != nil {
				return nil, nerr
			}
			if isLetterDigit(nch) {
				word = append(word, ch, nch)
			} else {
				if _, e := br.UnreadRune(); e != nil {
					return nil, e
				}
			}
		default:
			// Separator (or a leading apostrophe).
		}
		if len(word) > 0 && !isWordRune(ch) && !isApostrophe(ch) {
			flush(word)
			word = nil
		} else if len(word) > 0 && isApostrophe(ch) {
			// The apostrophe did not start an internal continuation
			// (trailing), or it was a separator before a word.
			if !isLetterDigit(ch) {
				// handled below via the separator path
			}
		}
		if len(word) > 0 && !isLetterDigit(ch) {
			// Either a separator ended the word, or an apostrophe
			// without a following letter/digit ended it.
			if !isWordRune(ch) {
				flush(word)
				word = nil
			} else {
				// Apostrophe kept: already extended or pending.
				_, _, aerr := br.ReadRune()
				_ = aerr
			}
		}
	}
	if len(word) > 0 {
		flush(word)
	}

	result := make([]WordCount, 0, len(counts))
	for w, c := range counts {
		result = append(result, WordCount{Word: w, Count: c})
	}
	sort.Slice(result, func(i, j int) bool {
		if result[i].Count != result[j].Count {
			return result[i].Count > result[j].Count
		}
		return result[i].Word < result[j].Word
	})
	if k < len(result) {
		result = result[:k]
	}
	return result, nil
}

// isLetterDigit reports whether ch is a Unicode letter or digit.
func isLetterDigit(ch rune) bool {
	return unicode.IsLetter(ch) || unicode.IsDigit(ch)
}

// isApostrophe reports whether ch is an apostrophe.
func isApostrophe(ch rune) bool {
	return ch == '\'' || ch == '’' || ch == '‛'
}

// isWordRune reports whether ch is a letter, digit, or apostrophe.
func isWordRune(ch rune) bool {
	return isLetterDigit(ch) || isApostrophe(ch)
}

var _ = utf8.RuneSelf
